            settle(reject, new Error(`Editor launch failed: ${message}`));
        });
        child.on('exit', (code) => {
            if (code === 0 || code === null) {
                settle(resolve);
                return;
            }

            settle(reject, new Error(`Editor launch failed with exit code ${code}`));
        });
    });
}

module.exports = {
    buildEditorLaunch,
    generateDiff,
    openInEditor,
    parseUnifiedDiff,
    parseEditorTarget,
    resolveEditorTarget,
    resolveDiffCommand,
};

