        expect(parseEditorTarget({ path: 'src/file.js:12' })).toEqual({ line: 12, path: 'src/file.js' });
        expect(parseEditorTarget({ path: 'src/file.js' })).toEqual({ line: 1, path: 'src/file.js' });
